#!/usr/bin/env node
/**
 * Hard-clean every Android build artifact so a stale APK can never be shipped
 * or re-installed.
 *
 * Deletes:
 *   - android/build, android/app/build            (Gradle outputs, dex, APKs)
 *   - android/.gradle, .gradle                    (Gradle project caches)
 *   - android/capacitor-cordova-android-plugins/build
 *   - android/app/src/main/assets/public          (stale synced web bundle)
 *   - android/app/src/main/assets/capacitor.plugins.json (regenerated by sync)
 *   - urbanwash-<variant>.apk (cached root APK of the CURRENT variant only)
 *   - apk-verify.log
 *
 * Never touches source, android-native/, or android-config/.
 */
import fs from "node:fs";
import path from "node:path";
import { VARIANT } from "./lib/variant.mjs";

// Only the CURRENT variant's cached root APK may be removed. The other
// variant's APK is an independent artifact and must survive this clean.
const TARGETS = [
  "android/build",
  "android/app/build",
  "android/.gradle",
  ".gradle",
  "android/capacitor-cordova-android-plugins/build",
  "android/app/src/main/assets/public",
  "android/app/src/main/assets/capacitor.plugins.json",
  `urbanwash-${VARIANT}.apk`,
  "apk-verify.log",
];

let removed = 0;
for (const target of TARGETS) {
  const abs = path.resolve(target);
  if (!fs.existsSync(abs)) {
    console.log(`  [skip] ${target} (absent)`);
    continue;
  }
  fs.rmSync(abs, { recursive: true, force: true });
  if (fs.existsSync(abs)) {
    console.error(`  [X] could not delete ${target} — close Android Studio / stop Gradle daemons and retry`);
    process.exit(1);
  }
  removed++;
  console.log(`  [del] ${target}`);
}

// Any APK left anywhere under android/ is a stale artifact by definition.
function sweepApks(dir) {
  if (!fs.existsSync(dir)) return;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (entry.name === "node_modules") continue;
      sweepApks(full);
    } else if (entry.name.endsWith(".apk") || entry.name.endsWith(".aab")) {
      fs.rmSync(full, { force: true });
      removed++;
      console.log(`  [del] ${full}`);
    }
  }
}
sweepApks(path.resolve("android"));

console.log(`  [OK] Android build artifacts cleaned (${removed} path(s) removed)`);
